<?php
declare(strict_types=1);
function stage59Ref(string $date,string $author='Silva, A.'):string {return $author.' ('.$date.'). Synthetic work. Publisher.';}
foreach(['pt','en','es']as$lang){
 foreach(['s.f.','s. f.','S.F.-a','s. f.-b','en prensa','EN PRENSA']as$date){foreach(['(Silva, %s).','Silva (%s).']as$shape){test('marcador espanhol liga chave declarada sem confirmar publicação '.$lang.md5($date.$shape),function()use($lang,$date,$shape){$doc=stage58Document($lang,[sprintf($shape,$date)],[stage59Ref($date)]);$before=$doc;$r=apaResults($doc,$lang);$a=$r['references.apa7']['evidence']['analysis'];same('conforme',$r['references.citation_matching']['status']);same('indeterminado',$r['references.apa7.citation_format']['status']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);same(1,$a['special_date_citations']);same(1,$a['matched_citations']);same(true,in_array('special_date_review',$a['citation_style_samples'][0]['issues'],true));same($before,$doc);same('29.0.0',$r['references.apa7']['rule_version']);same('18.0.0',$r['references.apa7.recognized_formats']['rule_version']);});}}
 foreach([['s.f.','n.d.'],['n.d.','s.f.'],['s.f.-a','s.d.-a'],['en prensa','in press'],['no prelo','en prensa']]as$pair){test('equivalência lexical preserva estado e sufixo '.$lang.md5(json_encode($pair)),function()use($lang,$pair){$r=stage58Results($lang,['(Silva, '.$pair[0].').'],[stage59Ref($pair[1])]);same('conforme',$r['references.citation_matching']['status']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});}
 foreach([['s.f.','2020'],['2020','s.f.'],['en prensa','2020'],['s.f.','en prensa'],['s.f.-a','s.f.-b'],['s.f.','s.f.-a']]as$pair){test('estados ou sufixos divergentes não provam obra ausente '.$lang.md5(json_encode($pair)),function()use($lang,$pair){$r=stage58Results($lang,['(Silva, '.$pair[0].').'],[stage59Ref($pair[1])]);same('indeterminado',$r['references.citation_matching']['status']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});}
 foreach(['s.f.','en prensa']as$date){
  test('chave realmente ausente só falha no subconjunto fechado '.$lang.$date,function()use($lang,$date){$r=stage58Results($lang,['(Absent, '.$date.').'],[stage59Ref($date)]);same('não conforme',$r['references.citation_matching']['status']);same('not_accepted',$r['references.apa7']['evidence']['admission_policy']['decision']);});
  test('erro local com marcador especial mantém bloqueio '.$lang.$date,function()use($lang,$date){$r=stage58Results($lang,['Silva & Costa ('.$date.').'],[stage59Ref($date,'Silva, A., & Costa, B.')]);same('conforme',$r['references.citation_matching']['status']);same('não conforme',$r['references.apa7.citation_format']['status']);same('not_accepted',$r['references.apa7']['evidence']['admission_policy']['decision']);});
  test('secundária especial liga apenas a fonte consultada '.$lang.$date,function()use($lang,$date){$marker=['pt'=>'como citado em','en'=>'as cited in','es'=>'como se citó en'][$lang];$r=stage58Results($lang,['(Original, 1900, '.$marker.' Silva, '.$date.').'],[stage59Ref($date)]);$a=$r['references.apa7']['evidence']['analysis'];same(1,$a['matched_citations']);same(0,$a['unresolved_citations']);same(true,$a['citation_samples'][0]['secondary']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});
  test('apud especial permanece proibido '.$lang.$date,function()use($lang,$date){$r=stage58Results($lang,['(Original, 1900, apud Silva, '.$date.').'],[stage59Ref($date)]);same('not_accepted',$r['references.apa7']['evidence']['admission_policy']['decision']);});
  test('duplicata com data especial permanece ambígua '.$lang.$date,function()use($lang,$date){$ref=stage59Ref($date);$r=stage58Results($lang,['(Silva, '.$date.').'],[$ref,$ref]);same('indeterminado',$r['references.citation_matching']['status']);same(1,$r['references.apa7']['evidence']['analysis']['ambiguous_matches']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});
  test('autor institucional especial não confirma identidade '.$lang.$date,function()use($lang,$date){$r=stage58Results($lang,['(World Health Organization, '.$date.').'],['World Health Organization. ('.$date.'). Synthetic report. Publisher.']);same('conforme',$r['references.citation_matching']['status']);same('indeterminado',$r['references.apa7.citation_format']['status']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});
 }
 foreach(['sf','s.f','enprensa','en prensa-a','en revisión']as$date){test('variante fora da gramática não gera falta de referência '.$lang.$date,function()use($lang,$date){$r=stage58Results($lang,['(Silva, '.$date.').'],[stage59Ref($date)]);same('indeterminado',$r['references.citation_matching']['status']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});}
 test('data especial da mesma autoria impede inferência numérica forte '.$lang,function()use($lang){$r=stage58Results($lang,['(Silva et al., 2020).'],[stage59Ref('2020','Silva, A., Costa, B., & Lima, C.'),stage59Ref('s.f.','Silva, B.')]);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);same('indeterminado',$r['references.apa7.citation_format']['status']);});
 test('contador não se limita às amostras de datas '.$lang,function()use($lang){$r=stage58Results($lang,array_fill(0,40,'(Silva, s.f.).'),[stage59Ref('s.f.')]);$a=$r['references.apa7']['evidence']['analysis'];same(40,$a['special_date_citations']);same(32,count($a['citation_style_samples']));same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});
 test('citação transcrita com s.f. não prova consulta ou ausência '.$lang,function()use($lang){$r=stage58Results($lang,['“(Absent, s.f.)”'],[stage59Ref('s.f.')]);same('indeterminado',$r['references.citation_matching']['status']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});
}
foreach(['s.f.','en prensa']as$date){test('painel e assinatura distinguem revisão de marcador '.$date,function()use($date){withDeskPanel(function($s,$r,$f,$pub,$path)use($date){$d=stage57Document('es',['(Silva, '.$date.').'],[stage59Ref($date)]);$z=new ZipArchive();$z->open($path);$z->addFromString('word/document.xml',docxParts(docxBody(array_column($d['paragraphs'],'text')))['word/document.xml']);$z->close();$f->submission->data['locale']='es_ES';$a=(new EstrabaoAdmissionBridge())->analyze($f);same('manual_review_required',$a['decision']);same(true,$a['special_date_review']);same(true,$a['reviewable']);same('0.44.0',$a['binding']['engine_version']);same('29.0.0',$a['binding']['rule_version']);$old=$a['binding'];$old['engine_version']='0.43.0';$old['rule_version']='28.0.0';$fingerprint=hash('sha256',json_encode($old));(new EstrabaoAdmissionReviewStore())->transaction(3,17,function(&$l)use($fingerprint){$l['events'][]=['sequence'=>1,'action'=>'approve','reviewer_id'=>77,'recorded_at'=>'2026-11-20T12:00:00Z','fingerprint'=>$fingerprint];});same(false,$s->view($r,17)['release_active']);});});}
test('data especial só na referência também orienta a conferência privada',function(){withDeskPanel(function($s,$r,$f,$pub,$path){$d=stage57Document('es',['(Silva, 2020).'],[stage59Ref('en prensa')]);$z=new ZipArchive();$z->open($path);$z->addFromString('word/document.xml',docxParts(docxBody(array_column($d['paragraphs'],'text')))['word/document.xml']);$z->close();$f->submission->data['locale']='es_ES';$a=(new EstrabaoAdmissionBridge())->analyze($f);same(true,$a['special_date_review']);same('manual_review_required',$a['decision']);$checks=apaResults($d,'es');same(0,$checks['references.apa7']['evidence']['analysis']['special_date_citations']);same(1,$checks['references.apa7']['evidence']['analysis']['special_date_references']);same('indeterminado',$checks['references.citation_matching']['status']);});});
foreach(['pt'=>'Data','en'=>'Date','es'=>'Fecha']as$lang=>$word){foreach(['s.f.','en prensa']as$date){test('rótulo de data não é presumido como autor ausente '.$lang.$date,function()use($lang,$word,$date){$r=stage58Results($lang,[$word.' ('.$date.').'],[stage59Ref($date)]);same('indeterminado',$r['references.citation_matching']['status']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);same(0,$r['references.apa7']['evidence']['analysis']['recognized_citations']);same(1,$r['references.apa7']['evidence']['analysis']['special_date_references']);});}}
